quotes: {
  id: "quotes",
  title: "Quotes (Table 1: 0001...)",
  desc: "Wisdom passages, reflections, and quotes in SQLite",
  prefix: "0001",
  saveEndpoint: `${API_BASE}/api/quote`,
  deleteEndpoint: `${API_BASE}/api/quote/delete`,
  getData: () => allQuotesList,
  columns: [
    { key: "idx", label: "IDX", format: (v, row) => `<span style="color:var(--accent); font-weight:700;">#${v ?? (row ? (row.idx ?? row.index) : '')}</span>` },
    { key: "main_content", label: "Content", format: v => `“${String(v).split('\n')[0].substring(0, 48)}${String(v).length > 48 ? '...' : ''}”` },
    { key: "context", label: "Context", format: v => v ? `<span style="color:var(--text-muted); font-size:0.8rem;">${String(v).split('\n')[0].substring(0, 32)}${String(v).length > 32 ? '...' : ''}</span>` : '—' },
    { key: "specific_id", label: "Specific Endpoint", format: v => {
      const s = availableSpecifics.find(item => item.id === v);
      return s ? `<span class="selected-val-badge">📍 ${s.name} · ${s.container ? s.container.name : (s.container_name || '')}</span>` : '—';
    }},
    { key: "date", label: "Date", format: (v, row) => {
      if (v && String(v).trim()) {
        return `<span style="font-family:'JetBrains Mono'; font-size:0.78rem;">${v}</span>`;
      }
      const s = availableSpecifics.find(item => item.id === (row ? row.specific_id : null));
      if (s && s.date && String(s.date).trim()) {
        return `<span style="font-family:'JetBrains Mono'; font-size:0.78rem; opacity:0.65;" title="Inherited fallback from endpoint: ${s.name}">📅 ${s.date} <span style="font-size:0.68rem; opacity:0.6;">(endpoint)</span></span>`;
      }
      return '—';
    }},
    { key: "theme_ids", label: "Themes", format: v => {
      const ids = Array.isArray(v) ? v : [];
      if (ids.length === 0) return '—';
      return ids.map(tid => {
        const t = availableThemes.find(item => item.id === tid);
        const name = t ? t.name : tid;
        return `<span class="chip-badge" style="font-size:0.72rem; background:var(--bg-input); border-color:var(--border-mid);">🏷️ ${name}</span>`;
      }).join(' ');
    }},
    { key: "usage_ids", label: "Usages", format: v => (v || []).map(uid => {
      const u = availableUsages.find(item => item.id === uid);
      return `<span class="chip-badge" style="font-size:0.72rem;">${u ? (u.icon || '') + ' ' + u.name : uid}</span>`;
    }).join(' ') || '—' },
    { key: "preference", label: "Preferences", format: v => {
      const ids = Array.isArray(v) ? v : [];
      if (ids.length === 0) return '—';
      return ids.map(qid => {
        const q = allQuotesList.find(item => item.id === qid);
        const label = q ? `#${q.idx ?? q.index}` : qid.substring(0, 8);
        return `<span class="chip-badge" style="font-size:0.72rem; color:var(--accent);">↪ ${label}</span>`;
      }).join(' ');
    }},
    { key: "backlinks", label: "Backlinks", format: v => {
      const links = Array.isArray(v) ? v : [];
      if (links.length === 0) return '—';
      return links.map(url => {
        try {
          const u = new URL(url);
          return `<a href="${url}" target="_blank" class="chip-badge" style="font-size:0.72rem; color:var(--accent); text-decoration:none;" onclick="event.stopPropagation()">🔗 ${u.hostname}</a>`;
        } catch (e) {
          return `<span class="chip-badge" style="font-size:0.72rem;">🔗 ${url.substring(0, 20)}</span>`;
        }
      }).join(' ');
    }}
  ],
  fields: [
    { key: "id", label: "ID (0001...)", type: "readonly" },
    { key: "idx", label: "Index / Sequence (#)", type: "number" },
    { key: "main_content", label: "Main Quote Content", type: "textarea", required: true },
    { key: "context", label: "Reflection Context", type: "textarea" },
    { key: "date", label: "Date (Flexible)", type: "text" },
    { key: "specific_id", label: "Specific Endpoint", type: "select", optionsSource: "specifics" },
    { key: "theme_ids", label: "Themes (Tree)", type: "multi_select", optionsSource: "themes" },
    { key: "usage_ids", label: "Usage Modes", type: "multi_select", optionsSource: "usages" },
    { key: "preference", label: "Preferences / Follow-ups (Quote IDs)", type: "json_array" },
    { key: "backlinks", label: "Backlinks (URLs)", type: "json_array" }
  ]
},
